argv:
$ErrorActionPreference='SilentlyContinue';$OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new();
$o=[ordered]@{};
$c=Get-NetTCPConnection -LocalPort 17448 -State Listen | Select-Object -First 1;
$o.listener=if($c){[ordered]@{pid=$c.OwningProcess;local=$c.LocalAddress;port=$c.LocalPort}}else{$null};
if($c){$p=Get-CimInstance Win32_Process -Filter "ProcessId=$($c.OwningProcess)";$o.process=[ordered]@{pid=$p.ProcessId;name=$p.Name;commandLine=$p.CommandLine;executable=$p.ExecutablePath}}
try{$x=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/operator-lifecycle' -TimeoutSec 3;$o.lifecycle=$x}catch{$o.lifecycleError=$_.Exception.Message}
try{$x=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/projects/control-plane?inspect=0' -TimeoutSec 3;$o.controlPlane=[ordered]@{object=$x.object;contract=$x.contract;checkedAt=$x.checkedAt;source=$x.source;counters=$x.counters}}catch{$o.controlPlaneError=$_.Exception.Message}
$o|ConvertTo-Json -Depth 8 -Compress
